INSERT IGNORE INTO sys_role_menu SELECT 1812120000000001,menu_id FROM sys_menu WHERE NOT EXISTS(SELECT 1 FROM sys_role_menu r WHERE r.role_id=1812120000000001 AND r.menu_id=sys_menu.menu_id);
INSERT INTO sys_role_menu SELECT 1812120000000002,m.menu_id FROM sys_menu m WHERE m.menu_id IN(8100000,8100100) AND NOT EXISTS(SELECT 1 FROM sys_role_menu r WHERE r.role_id=1812120000000002 AND r.menu_id=m.menu_id);
INSERT INTO sys_role_menu SELECT 910001,m.menu_id FROM sys_menu m WHERE (m.menu_id IN(8100000,8100100) OR m.menu_id IN(SELECT rm.menu_id FROM sys_role_menu rm WHERE rm.role_id=1812120000000002)) AND NOT EXISTS(SELECT 1 FROM sys_role_menu r WHERE r.role_id=910001 AND r.menu_id=m.menu_id);
INSERT INTO sys_role_menu SELECT 910002,m.menu_id FROM sys_menu m WHERE m.menu_id BETWEEN 8100000 AND 8100302 AND NOT EXISTS(SELECT 1 FROM sys_role_menu r WHERE r.role_id=910002 AND r.menu_id=m.menu_id);
