CREATE TABLE IF NOT EXISTS sys_user_role(user_id BIGINT NOT NULL,role_id BIGINT NOT NULL,PRIMARY KEY(user_id,role_id),KEY ix_role_users(role_id,user_id),FOREIGN KEY(user_id) REFERENCES sys_user(user_id),FOREIGN KEY(role_id) REFERENCES sys_role(role_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sys_permission_audit(id BIGINT AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT NOT NULL,action VARCHAR(32) NOT NULL,target_id BIGINT NOT NULL,detail TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
UPDATE sys_role SET role_name='管理员' WHERE role_id=1812120000000001;
UPDATE sys_role SET role_name='学生',role_key='student' WHERE role_id=1812120000000002;
DELETE rm FROM sys_role_menu rm JOIN sys_menu m ON m.menu_id=rm.menu_id WHERE rm.role_id IN(1812120000000002,910001) AND (m.menu_id IN(1,100,101,102,105,107,116) OR m.perms LIKE 'system:user:%' OR m.perms LIKE 'system:role:%' OR m.perms LIKE 'system:menu:%' OR m.perms LIKE 'system:dict:%' OR m.perms LIKE 'system:notice:%' OR m.perms LIKE 'system:excelImport:%');
CREATE TABLE IF NOT EXISTS sys_permission_lock(id INT PRIMARY KEY) ENGINE=InnoDB;
